const labels = raw.map(d => d[0]);
const prices = raw.map(d => d[1]);
const n = prices.length;

// Month-over-month
const mom = [null];
for (let i = 1; i < n; i++) mom.push(+(prices[i] - prices[i-1]).toFixed(3));

// 12-month rolling average
const rolling12 = [];
for (let i = 0; i < n; i++) {
  if (i < 11) { rolling12.push(null); continue; }
  let s = 0; for (let j = i-11; j <= i; j++) s += prices[j];
  rolling12.push(+(s/12).toFixed(3));
}

// Chart.js defaults
Chart.defaults.color = '#8b90aa';
Chart.defaults.borderColor = '#2e3350';
Chart.defaults.font.family = "'Inter','Segoe UI',system-ui,sans-serif";

// ═══ MAIN TIME SERIES CHART ═══════════════════════════════════════
(function() {
